/**
 * Sprite forge — characters that match the story.
 *
 * The video studio's pixel recipes know two sprites, a kid and a robot. Here a short description of a
 * character ("a tired old baker, bald, white apron", "a small orange stray cat") becomes a 16×16 sprite
 * in the same hand-pixelled style: a template chosen by what the character IS, coloured by what the
 * description SAYS. Nothing is generated by a model — a diffusion model cannot draw a readable 16×16
 * figure — so every sprite is deterministic, authentic to the look, and testable.
 *
 * Letters in a template: K outline · S skin/face · H hair, fur or top · C body · P legs or paws ·
 * A accent (hat, apron, visor, beak) · W eye white · M mouth (drawn only while the character talks).
 *
 * Pure: no database, no network, no clock, no randomness (defaults come from a hash of the name).
 */

const HUMAN_BODY = ['...KKCCCCCCKK...', '..KSKCCCCCCKSK..', '..KSKCCCCCCKSK..', '...KKCCCCCCKK...', '....KPPPPPPK....', '....KPPKKPPK....', '....KPPK.KPPK...', '....KKK...KKK...'];
const APRON_BODY = ['...KKCCCCCCKK...', '..KSKCAAAACKSK..', '..KSKCAAAACKSK..', '...KKCAAAACKK...', '....KPAAAAPK....', '....KPPKKPPK....', '....KPPK.KPPK...', '....KKK...KKK...'];
const ROBOT_BODY = ['..KPKCCCCCCKPK..', '..KPKCCCCCCKPK..', '...KKCCCCCCKK...', '....KPPPPPPK....', '....KPPKKPPK....', '....KPPK.KPPK...', '....KKK...KKK...'];
const HEADS = {
  short: ['.....KKKKKK.....', '....KHHHHHHK....', '...KHHHHHHHHK...', '...KHSSSSSSHK...', '...KSWKSSWKSK...', '...KSSSSSSSSK...', '...KSSSMMSSSK...', '....KSSSSSSK....'],
  long: ['.....KKKKKK.....', '....KHHHHHHK....', '...KHHHHHHHHK...', '..KHHSSSSSSHHK..', '..KHSWKSSWKSHK..', '..KHSSSSSSSSHK..', '..KHSSSMMSSSHK..', '..KHKSSSSSSKHK..'],
  bald: ['.....KKKKKK.....', '....KSSSSSSK....', '...KSSSSSSSSK...', '...KSSSSSSSSK...', '...KSWKSSWKSK...', '...KSSSSSSSSK...', '...KSSSMMSSSK...', '....KSSSSSSK....'],
  hat: ['......KKKK......', '.....KAAAAK.....', '....KAAAAAAK....', '..KAAAAAAAAAAK..', '...KSWKSSWKSK...', '...KSSSSSSSSK...', '...KSSSMMSSSK...', '....KSSSSSSK....'],
  beard: ['.....KKKKKK.....', '....KHHHHHHK....', '...KHHHHHHHHK...', '...KHSSSSSSHK...', '...KSWKSSWKSK...', '...KHSSSSSSHK...', '...KHHHMMHHHK...', '....KHHHHHHK....'],
};

/** Whole-figure templates. `closed` is the letter a mouth pixel takes when the character is not talking. */
export const TEMPLATES = Object.freeze({
  'human-short': { rows: [...HEADS.short, ...HUMAN_BODY], closed: 'S' },
  'human-long': { rows: [...HEADS.long, ...HUMAN_BODY], closed: 'S' },
  'human-bald': { rows: [...HEADS.bald, ...HUMAN_BODY], closed: 'S' },
  'human-hat': { rows: [...HEADS.hat, ...HUMAN_BODY], closed: 'S' },
  'human-beard': { rows: [...HEADS.beard, ...HUMAN_BODY], closed: 'H' },
  astronaut: { rows: ['.....KKKKKK.....', '....KAAAAAAK....', '...KAAAAAAAAK...', '...KASSSSSSAK...', '...KAWKSSWKAK...', '...KASSSSSSAK...', '...KASSMMSSAK...', '....KAAAAAAK....',
    '...KKAAAAAAKK...', '..KAKAACCAAKAK..', '..KAKAACCAAKAK..', '...KKAAAAAAKK...', '....KAAAAAAK....', '....KAAKKAAK....', '....KAAK.KAAK...', '....KKK...KKK...'], closed: 'S' },
  robot: { rows: ['......KKKK......', '.....K.WW.K.....', '...KKKKKKKKKK...', '..KCCCCCCCCCCK..', '..KCWWKCCWWKCK..', '..KCWKKCCWKKCK..', '..KCCCCCCCCCCK..', '..KCCMMMMMMCCK..', '...KKKKKKKKKK...', ...ROBOT_BODY], closed: 'C' },
  'robot-round': { rows: ['.......KK.......', '.......KK.......', '....KKKKKKKK....', '...KCCCCCCCCK...', '..KCKKKKKKKKCK..', '..KCKWWKKWWKCK..', '..KCKKKKKKKKCK..', '..KCCCMMMMCCCK..', '...KKKKKKKKKK...', ...ROBOT_BODY], closed: 'C' },
  cat: { rows: ['..K......K......', '.KHK....KHK.....', '.KHHKKKKHHK.....', '.KHHHHHHHHK.....', '.KHWKHHWKHK.....', '.KHHHHHHHHK.....', '.KHHHMMHHHK.....', '..KHHHHHHK......',
    '..KKCCCCKK...K..', '.KHKCCCCKHK.KHK.', '.KHKCCCCKHK.KHK.', '..KKCCCCKKKKHK..', '...KHHHHHHHHK...', '...KPPKKPPKK....', '...KPPK.KPPK....', '...KKK...KKK....'], closed: 'H' },
  dog: { rows: ['...KKKKKKKK.....', '.KKHHHHHHHHKK...', 'KAAKHHHHHHKAAK..', 'KAAKHHHHHHKAAK..', 'KAAKWKHHWKKAAK..', '.KKKHHHHHHKKK...', '...KHHMMHHK.....', '....KKHHKK......',
    '...KKCCCCKK.....', '..KHKCCCCKHK....', '..KHKCCCCKHK.K..', '...KKCCCCKKKHK..', '....KHHHHHHKK...', '....KPPKKPPK....', '....KPPK.KPPK...', '....KKK...KKK...'], closed: 'H' },
  ghost: { rows: ['.....KKKKKK.....', '...KKHHHHHHKK...', '..KHHHHHHHHHHK..', '..KHHHHHHHHHHK..', '..KHHKKHHKKHHK..', '..KHHKKHHKKHHK..', '..KHHHHHHHHHHK..', '..KHHHHMMHHHHK..',
    '..KHHHHHHHHHHK..', '.KHKHHHHHHHHKHK.', '.KKKHHHHHHHHKKK.', '..KHHHHHHHHHHK..', '..KHHHHHHHHHHK..', '..KHHHHHHHHHHK..', '..KHKKHHKKHHKK..', '..KK..KK..KK....'], closed: 'H' },
  alien: { rows: ['..K..........K..', '...K........K...', '....KKKKKKKK....', '...KCCCCCCCCK...', '..KCCCCCCCCCCK..', '..KCWWKCCWWKCK..', '..KCWKKCCWKKCK..', '..KCCCCCCCCCCK..',
    '...KCCCMMCCCK...', '....KKKKKKKK....', '...KCKAAAAKCK...', '...KCKAAAAKCK...', '....KKAAAAKK....', '....KPPKKPPK....', '....KPPK.KPPK...', '....KKK...KKK...'], closed: 'C' },
  bird: { rows: ['................', '.....KKKKKK.....', '....KHHHHHHK....', '...KHHHHHHHHK...', '...KHWKHHWKHK...', '...KHHHAAHHHK...', '...KHHHMMHHHK...', '..KKHHHHHHHHKK..',
    '.KHHKCCCCCCKHHK.', '.KHHKCCCCCCKHHK.', '.KHKKCCCCCCKKHK.', '..KKKCCCCCCKKK..', '....KKCCCCKK....', '.....KAKKAK.....', '.....KAK.KAK....', '....KKK...KKK...'], closed: 'A' },
});
for (const [name, t] of Object.entries(TEMPLATES)) {
  if (t.rows.length !== 16 || t.rows.some(r => r.length !== 16 || /[^.KSHCPAWM]/.test(r))) throw new Error(`sprite template ${name} is not a 16×16 grid of known letters`);
}

/** Colour words → colours from the 28-colour NES subset the 8-bit look is quantised to. */
export const COLOURS = Object.freeze({
  red: '#f83800', crimson: '#a80020', blue: '#0078f8', navy: '#0000fc', sky: '#3cbcfc', cyan: '#00e8d8', teal: '#008888', green: '#00b800', lime: '#b8f818', olive: '#005800',
  yellow: '#f8b800', gold: '#f8b800', orange: '#fca044', ginger: '#fca044', purple: '#6844fc', violet: '#6844fc', magenta: '#d800cc', pink: '#f878f8',
  brown: '#ac7c00', tan: '#fca044', white: '#fcfcfc', silver: '#bcbcbc', grey: '#bcbcbc', gray: '#bcbcbc', black: '#000000', dark: '#503000', blonde: '#f8b800', cream: '#fce0a8',
});
const SKIN = { default: '#fce0a8', tan: '#fca044', brown: '#ac7c00', dark: '#881400', pale: '#fcfcfc' };
const PART = [
  ['skin', /^(skin|skinned|complexion)$/], ['hair', /^(hair|haired|beard|bearded|fur|furred|furry|feathers?|feathered|mane|tabby|stripes?)$/],
  ['legs', /^(pants|trousers|jeans|shorts|legs|boots|shoes|skirt|leggings|paws)$/],
  ['accent', /^(hat|cap|helmet|apron|scarf|cape|crown|hood|visor|bandana|beak|collar|badge|bow|tie|belt|eyes?|lights?|antenna|trim)$/],
  ['main', /^(shirt|coat|jacket|sweater|dress|suit|robe|uniform|armou?r|body|tunic|hoodie|overalls|spacesuit|cloak|vest|shell|plating|metal|paint)$/],
];
const KIND = [
  ['cat', /\b(cat|kitten|kitty|tomcat|lynx|tiger|lion|panther)\b/], ['dog', /\b(dog|puppy|pup|hound|wolf|fox|coyote)\b/],
  ['bird', /\b(bird|owl|parrot|crow|raven|chicken|hen|rooster|duck|penguin|pigeon|sparrow|seagull|gull|eagle|hawk)\b/],
  ['ghost', /\b(ghost|spirit|phantom|spectre|specter|wraith|spook)\b/], ['alien', /\b(alien|martian|monster|creature|goblin|slime|blob|extraterrestrial)\b/],
  ['robot', /\b(robot|android|droid|machine|automaton|bot|drone|cyborg|mech)\b/], ['astronaut', /\b(astronauts?|cosmonauts?|space\s?suit|spaceman|spacewoman|diver)\b/],
];

const FEMALE = /\b(long hair|long-haired|girl|woman|lady|princess|queen|mother|mom|grandma|grandmother|sister|daughter|aunt|heroine|she|her|hers)\b/;
const MALE = /\b(man|boy|king|prince|father|dad|grandpa|grandfather|brother|son|uncle|he|his|him|beard|bearded)\b/;
const NECKWEAR = /^(collar|scarf|bandana|bow|tie)$/;

const hash = s => { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const pick = (list, seed) => list[seed % list.length];
const lumOf = hex => { const n = parseInt(hex.slice(1), 16); return 0.3 * ((n >> 16) & 255) + 0.59 * ((n >> 8) & 255) + 0.11 * (n & 255); };

/** "The Old Baker!" → "baker": a short lower-case name the script and the renderer can both use. */
export function castName(raw, fallback = 'hero') {
  const w = String(raw || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g, ' ').trim().split(/\s+/).filter(x => x && !/^(the|a|an|old|young|little|big|mr|mrs|ms|dr)$/.test(x));
  const name = (w[w.length - 1] || '').replace(/^[0-9]+/, '').slice(0, 12);
  return name || fallback;
}

/** What a description says: the kind of figure, its variant, and any colours tied to a part. */
export function readLook(look, name = '') {
  const text = `${String(look || '')} ${String(name || '')}`.toLowerCase();
  const kind = (KIND.find(([, re]) => re.test(text)) || ['human'])[0];
  let template = kind;
  if (kind === 'robot') template = /\b(round|dome|small|little|tiny|drone|cute|ball)\b/.test(text) ? 'robot-round' : 'robot';
  if (kind === 'human') {
    template = /\b(bald|shaved)\b/.test(text) ? 'human-bald'
      : /\b(hat|cap|crown|helmet|hood|wizard|witch|chef|captain|pirate|cowboy|sailor|king|queen|soldier|guard|miner|firefighter)\b/.test(text) ? 'human-hat'
      : /\b(beard|bearded)\b/.test(text) ? 'human-beard'
      : FEMALE.test(text) ? 'human-long'
      : /\b(grandpa|grandfather|dwarf|old man|elder|hermit)\b/.test(text) ? 'human-beard' : 'human-short';
  }
  const apron = kind === 'human' && /\b(apron|baker|cook|blacksmith|smith|butcher|barista|painter|gardener|doctor|nurse|scientist|lab coat)\b/.test(text);
  const said = {}, loose = [], nouns = {};
  const tokens = text.replace(/[^a-z0-9 -]/g, ' ').split(/[\s-]+/).filter(Boolean);
  tokens.forEach((tok, i) => {
    if (!Object.hasOwn(COLOURS, tok)) return;
    const next = tokens.slice(i + 1, i + 3);
    let part = null;
    for (const n of next) { const hit = PART.find(([, re]) => re.test(n)); if (hit) { part = hit[0]; break; } if (KIND.some(([k, re]) => k === kind && re.test(n))) { part = 'primary'; break; } }
    if (part) { if (!(part in said)) { said[part] = tok; nouns[part] = next.find(n => PART.some(([p, re]) => p === part && re.test(n))) || null; } } else loose.push(tok);
  });
  return { kind, template, apron, said, loose, nouns };
}

/**
 * Build one sprite. `taken` is the set of main colours already used by other cast members, so two
 * characters nobody described still look different.
 * @returns {{ name, look, kind, template, rows: string[16], closed, colors: {K,S,H,C,P,A,W,M}, why: string[] }}
 */
export function forgeSprite({ name, look }, { style = '8bit', taken = new Set(), female = false } = {}) {
  const id = castName(name), r = readLook(look, name), seed = hash(id + '|' + String(look || ''));
  // the script's description gave no gender but the request did ("a keeper and her dog")
  const fromRequest = female && r.template === 'human-short';
  if (fromRequest) r.template = 'human-long';
  const t = TEMPLATES[r.template];
  let rows = [...t.rows];
  if (r.apron) rows = [...rows.slice(0, 8), ...APRON_BODY];
  const why = [`${r.template}${r.apron ? ' with apron' : ''} (from "${String(look || name).slice(0, 60)}")`];
  if (fromRequest) why.push('long hair: the request says she is a woman');
  const col = w => COLOURS[w];
  const loose = [...r.loose];
  const takeLoose = () => loose.shift();
  const colors = { K: '#000000', W: '#fcfcfc', M: '#a80020', S: SKIN.default, H: COLOURS.brown, C: COLOURS.red, P: COLOURS.blue, A: COLOURS.white };
  const animal = ['cat', 'dog', 'bird', 'ghost'].includes(r.kind);
  const primaryWord = r.said.primary || (animal ? r.said.hair : r.said.main) || (animal || r.kind === 'robot' || r.kind === 'alien' ? takeLoose() : undefined);

  if (r.kind === 'human' || r.kind === 'astronaut') {
    const skinWord = r.said.skin; colors.S = SKIN[skinWord] || (skinWord && col(skinWord)) || pick([SKIN.default, SKIN.default, SKIN.tan, SKIN.brown, SKIN.dark], seed >>> 3);
    colors.H = col(r.said.hair) || pick([COLOURS.brown, COLOURS.dark, COLOURS.blonde, COLOURS.ginger, COLOURS.grey, COLOURS.crimson], seed >>> 7);
    const mains = ['red', 'blue', 'green', 'purple', 'yellow', 'teal', 'pink', 'orange'].filter(c => !taken.has(COLOURS[c]));
    colors.C = col(r.said.main) || col(takeLoose()) || COLOURS[pick(mains.length ? mains : ['red'], seed >>> 11)];
    colors.P = col(r.said.legs) || pick([COLOURS.navy, COLOURS.brown, COLOURS.teal, COLOURS.grey, COLOURS.olive].filter(c => c !== colors.C), seed >>> 15);
    colors.A = col(r.said.accent) || (r.kind === 'astronaut' ? COLOURS.white : r.apron ? COLOURS.white : pick([COLOURS.yellow, COLOURS.red, COLOURS.navy, COLOURS.purple, COLOURS.olive].filter(c => c !== colors.C), seed >>> 19));
    if (r.kind === 'astronaut') { colors.A = col(r.said.main) || col(r.said.accent) || colors.A; colors.C = col(r.said.accent && r.said.main ? r.said.accent : '') || pick([COLOURS.red, COLOURS.blue, COLOURS.orange, COLOURS.green].filter(c => !taken.has(c)), seed >>> 11) || COLOURS.red; }
  } else if (r.kind === 'robot' || r.kind === 'alien') {
    const bodies = (r.kind === 'robot' ? ['red', 'silver', 'sky', 'yellow', 'teal', 'orange'] : ['green', 'purple', 'lime', 'teal', 'pink']).filter(c => !taken.has(COLOURS[c]));
    colors.C = col(primaryWord) || col(r.said.main) || COLOURS[pick(bodies.length ? bodies : ['silver'], seed >>> 5)];
    colors.P = col(r.said.legs) || pick([COLOURS.blue, COLOURS.black, COLOURS.navy, COLOURS.teal].filter(c => c !== colors.C), seed >>> 9);
    colors.A = col(r.said.accent) || col(takeLoose()) || pick([COLOURS.yellow, COLOURS.sky, COLOURS.white, COLOURS.magenta].filter(c => c !== colors.C), seed >>> 13);
    colors.W = r.kind === 'alien' ? COLOURS.white : col(r.said.accent) || '#fcfcfc';
    colors.M = r.kind === 'robot' ? '#000000' : '#a80020';
  } else {
    const furs = { cat: ['orange', 'grey', 'black', 'white', 'brown', 'cream'], dog: ['brown', 'cream', 'grey', 'white', 'black'], bird: ['blue', 'red', 'yellow', 'white', 'black', 'green'], ghost: ['white'] }[r.kind];
    colors.H = col(primaryWord) || col(r.said.hair) || COLOURS[pick(furs.filter(c => !taken.has(COLOURS[c])).concat(furs[0]), seed >>> 5)];
    colors.C = col(r.said.main) || (r.kind === 'ghost' ? colors.H : lumOf(colors.H) > 200 ? COLOURS.grey : COLOURS.cream);
    colors.P = col(r.said.legs) || (r.kind === 'ghost' ? colors.H : lumOf(colors.H) > 200 ? COLOURS.grey : COLOURS.white);
    // a collar, scarf or bow goes round the neck (letter S, unused in these figures); it must not recolour a dog's ears
    const neck = (r.kind === 'cat' || r.kind === 'dog') && NECKWEAR.test(r.nouns.accent || '') && col(r.said.accent);
    if (neck) { rows[8] = rows[8].replace(/C/g, 'S'); colors.S = neck === '#000000' ? '#7c7c7c' : neck; why.push(`${r.said.accent} ${r.nouns.accent} drawn at the neck`); }
    colors.A = (!neck && col(r.said.accent)) || (r.kind === 'bird' ? COLOURS.orange : r.kind === 'dog' ? (lumOf(colors.H) > 150 ? COLOURS.brown : COLOURS.dark) : COLOURS.pink);
    colors.W = r.kind === 'cat' ? COLOURS.lime : '#fcfcfc';
    colors.M = r.kind === 'ghost' ? '#000000' : COLOURS.pink;
    if (r.kind === 'ghost') colors.W = '#000000';
  }
  // A body or accent in pure outline-black would erase the drawing; hair, fur and legs may be black.
  for (const k of ['C', 'A']) if (colors[k] === '#000000') colors[k] = '#7c7c7c';
  // Parts that touch must differ, or the hat disappears into the coat and the face into the helmet.
  if (r.kind === 'human' && colors.A === colors.C) colors.A = [COLOURS.yellow, COLOURS.white, COLOURS.navy].find(c => c !== colors.C && c !== colors.S);
  if ((r.kind === 'human' || r.kind === 'astronaut') && (colors.S === colors.A || colors.S === colors.C)) colors.S = [SKIN.default, SKIN.brown, SKIN.dark].find(c => c !== colors.A && c !== colors.C);
  if (r.kind === 'human' && colors.H === colors.S) colors.H = [COLOURS.dark, COLOURS.brown, COLOURS.grey].find(c => c !== colors.S);
  if (style === '2bit') {
    // Four shades only: place every role on its own step of the luminance ramp so the figure stays readable in any 4-colour palette.
    const step = { d0: '#202020', d1: '#606060', l0: '#a0a0a0', l1: '#e0e0e0' };
    const ramp = animal ? { K: step.d0, H: step.l0, C: step.l1, P: step.l1, A: step.d1, S: step.d1, W: step.l1, M: step.d0 }
      : r.kind === 'robot' || r.kind === 'alien' ? { K: step.d0, C: step.l0, P: step.d1, A: step.l1, S: step.l1, H: step.d1, W: step.l1, M: step.d0 }
      : { K: step.d0, S: step.l1, H: step.d1, C: step.l0, P: step.d1, A: lumOf(colors.A) > 150 ? step.l1 : step.d1, W: step.l1, M: step.d0 };
    if (r.kind === 'ghost') { ramp.H = step.l1; ramp.C = step.l1; ramp.W = step.d0; }
    if (r.kind === 'cat') ramp.W = step.l1;
    Object.assign(colors, ramp); why.push('colours reduced to four shades');
  }
  taken.add(r.kind === 'human' || r.kind === 'astronaut' || r.kind === 'robot' || r.kind === 'alien' ? colors.C : colors.H);
  for (const [part, word] of Object.entries(r.said)) why.push(`${word} ${part === 'primary' ? r.kind : part} (said)`);
  return { name: id, look: String(look || '').slice(0, 160), kind: r.kind, template: r.template + (r.apron ? '+apron' : ''), rows, closed: t.closed, colors, why };
}

/** Forge a whole cast with distinct names and, where nothing was said, distinct colours. */
export function forgeCast(cast, { style = '8bit', request = '' } = {}) {
  const taken = new Set(), names = new Set(), out = [];
  // "a keeper and her dog": when exactly one cast member is a person and no description gives a gender, the request's word applies to that person
  const looks = (cast || []).map(c => `${c?.look || ''} ${c?.name || ''}`.toLowerCase());
  const people = looks.map((l, i) => readLook(cast[i]?.look || '', cast[i]?.name || '').kind === 'human' ? i : -1).filter(i => i >= 0);
  const req = String(request || '').toLowerCase();
  const she = people.length === 1 && FEMALE.test(req) && !/\b(he|his|him)\b/.test(req) && !looks.some(l => FEMALE.test(l) || MALE.test(l)) ? people[0] : -1;
  for (const [i, c] of (cast || []).entries()) {
    const s = forgeSprite({ name: c?.name || `p${i + 1}`, look: c?.look || c?.name || '' }, { style, taken, female: i === she });
    let n = s.name; let k = 2;
    while (names.has(n)) n = `${s.name.slice(0, 10)}${k++}`;
    names.add(n); out.push({ ...s, name: n });
  }
  return out;
}

/** Raw RGBA pixels of a sprite frame (talking or not), for previews and tests. */
export function spritePixels(sprite, { talk = false } = {}) {
  const px = Buffer.alloc(16 * 16 * 4);
  sprite.rows.forEach((row, y) => [...row].forEach((ch, x) => {
    if (ch === '.') return;
    const letter = ch === 'M' && !talk ? sprite.closed : ch;
    const n = parseInt(sprite.colors[letter].slice(1), 16), i = (y * 16 + x) * 4;
    px[i] = (n >> 16) & 255; px[i + 1] = (n >> 8) & 255; px[i + 2] = n & 255; px[i + 3] = 255;
  }));
  return px;
}
